<?php
session_start();include('check-login.php');include('dbstring.php');include_once('transport-utils.php');if(!transport_is_admin()){http_response_code(403);exit('Administrator access required.');}transport_ensure_tables($con);$msg='';function tsa($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if(isset($_POST['assign_transport'])){list($ok,$message)=transport_assign_student($con,trim((string)$_POST['userid']),trim((string)$_POST['routeid']),trim((string)$_POST['stopid']),isset($_SESSION['USERID'])?$_SESSION['USERID']:'');$msg=$message;}
$routes=array();$r=mysqli_query($con,"SELECT tr.routeid,tr.routename,tr.fee,v.vehiclename,v.capacity,(SELECT COUNT(*) FROM tblstudenttransport st WHERE st.routeid=tr.routeid AND st.status='active') assigned FROM tbltransportroute tr LEFT JOIN tbltransportvehicle v ON v.vehicleid=tr.vehicleid WHERE tr.status='active' ORDER BY tr.routename");if($r)while($x=mysqli_fetch_assoc($r))$routes[]=$x;$stops=array();$r=mysqli_query($con,"SELECT * FROM tbltransportstop WHERE status='active' ORDER BY routeid,sortorder,stopname");if($r)while($x=mysqli_fetch_assoc($r))$stops[]=$x;$students=array();$r=mysqli_query($con,"SELECT userid,CONCAT_WS(' ',firstname,othernames,surname) name FROM tblsystemuser WHERE systemtype='Student' AND status='active' ORDER BY firstname,surname");if($r)while($x=mysqli_fetch_assoc($r))$students[]=$x;$assigned=array();$r=mysqli_query($con,"SELECT st.*,CONCAT_WS(' ',su.firstname,su.othernames,su.surname) studentname,tr.routename,ts.stopname FROM tblstudenttransport st INNER JOIN tblsystemuser su ON su.userid=st.userid LEFT JOIN tbltransportroute tr ON tr.routeid=st.routeid LEFT JOIN tbltransportstop ts ON ts.stopid=st.stopid WHERE st.status='active' ORDER BY tr.routename,studentname");if($r)while($x=mysqli_fetch_assoc($r))$assigned[]=$x;
?>
<!doctype html><html><head><?php include('links.php');?><title>Student Transport Assignment</title><style>body{background:#f4f8fb;font-family:Arial;color:#17314b}.tsa{max-width:1050px;margin:25px auto;background:#fff;padding:24px;border-radius:16px}.form{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.form select{padding:10px;background:#fff;color:#102a43;border:1px solid #7893aa;border-radius:7px}.form button{background:#087443;color:#fff;border:0;border-radius:8px;padding:11px}.tsa table{width:100%;border-collapse:collapse;margin-top:20px}.tsa td,.tsa th{padding:9px;border-bottom:1px solid #dce6ee;text-align:left}@media(max-width:700px){.tsa{margin:8px;padding:14px}.form{grid-template-columns:1fr}}</style></head><body><main class="tsa"><p><a href="transport-management.php">← Transport setup</a></p><h1>Student Transport Assignment</h1><p>Assign a student to one active route and pickup stop. Reassigning a student updates their current route.</p><?php if($msg!=='')echo '<p>'.tsa($msg).'</p>';?><form method="post" class="form"><select name="userid" required><option value="">Choose student</option><?php foreach($students as $s){?><option value="<?php echo tsa($s['userid']);?>"><?php echo tsa($s['name'].' — '.$s['userid']);?></option><?php }?></select><select name="routeid" required><option value="">Choose route</option><?php foreach($routes as $r){?><option value="<?php echo tsa($r['routeid']);?>"><?php echo tsa($r['routename'].' ('.$r['assigned'].'/'.$r['capacity'].')');?></option><?php }?></select><select name="stopid"><option value="">No stop selected</option><?php foreach($stops as $s){?><option value="<?php echo tsa($s['stopid']);?>"><?php echo tsa($s['stopname'].' — '.$s['pickuptime']);?></option><?php }?></select><button name="assign_transport">Save Student Transport</button></form><h2>Active Student Transport List</h2><table><tr><th>Student</th><th>Route</th><th>Pickup Stop</th></tr><?php foreach($assigned as $a){?><tr><td><?php echo tsa($a['studentname']);?></td><td><?php echo tsa($a['routename']);?></td><td><?php echo tsa($a['stopname']);?></td></tr><?php }?></table></main></body></html>
